--- /dev/null
+++ b/scripts/check-worker.mjs
@@ -0,0 +1,34 @@
+// Exercise the production module worker without opening a browser or serving files.
+import { Worker } from 'node:worker_threads';
+import assert from 'node:assert/strict';
+const workerUrl = new URL('../render-worker.js', import.meta.url).href;
+const adapter = `
+import { parentPort } from 'node:worker_threads';
+globalThis.self = { postMessage: (data, transfer) => parentPort.postMessage(data, transfer) };
+await import(${JSON.stringify(workerUrl)});
+parentPort.on('message', data => self.onmessage({ data }));
+parentPort.postMessage({ ready: true });
+`;
+await new Promise((resolve, reject) => {
+  const worker = new Worker(new URL(`data:text/javascript,${encodeURIComponent(adapter)}`));
+  const timer = setTimeout(() => { worker.terminate(); reject(new Error('Worker render timed out')); }, 30000);
+  worker.on('error', error => { clearTimeout(timer); reject(error); });
+  worker.on('message', data => {
+    if (data.ready) {
+      worker.postMessage({ width: 640, height: 480, samples: 8, seed: 17042, colors: { 0: [0.2, 0.7, 0.3], 1: [0.8, 0.3, 0.6], 6: [0.9, 0.7, 0.2], 7: [0.4, 0.7, 0.9] } });
+      return;
+    }
+    try {
+      assert(!data.error, data.error);
+      assert.equal(data.frame.byteLength, 640 * 480 * 4);
+      assert([4, 8].includes(data.sample));
+      if (data.done) {
+        assert.equal(data.sample, 8);
+        clearTimeout(timer);
+        worker.terminate();
+        console.log('Production worker passed: randomized materials at 640 × 480, progressive frames, transferable pixel buffers, and completion.');
+        resolve();
+      }
+    } catch (error) { clearTimeout(timer); worker.terminate(); reject(error); }
+  });
+});
