+static int width, height, pass;
+static uint32_t sceneSeed;
+static Vec* accumulation = nullptr;
+static unsigned char* pixels = nullptr;
+extern "C" {
+void setup(int w, int h, int seed, double r1, double g1, double b1, double r2, double g2, double b2) {
+  width=w; height=h; pass=0; sceneSeed=seed;
+  free(accumulation); free(pixels);
+  accumulation = (Vec*)calloc(w*h, sizeof(Vec)); pixels = (unsigned char*)calloc(w*h*4, 1);
+  spheres[0].c=Vec(r1,g1,b1); spheres[1].c=Vec(r2,g2,b2);
+  // Keep the mirror and glass materials while tinting their reflectance.
+  spheres[6].c=Vec(.65+.349*r1/.75,.65+.349*g1/.75,.65+.349*b1/.75);
+  spheres[7].c=Vec(.65+.349*r2/.75,.65+.349*g2/.75,.65+.349*b2/.75);
+}
+unsigned char* buffer() { return pixels; }
+void render_rows(int start, int end) {
+  Ray cam(Vec(50,52,295.6), Vec(0,-0.042612,-1).norm());
+  Vec cx=Vec(width*.5135/height), cy=(cx%cam.d).norm()*.5135;
+  for(int row=start;row<end;row++) {
+    int y=height-row-1;
+    unsigned short Xi[3]={(unsigned short)(sceneSeed+pass*1031),(unsigned short)(sceneSeed>>16),(unsigned short)(y*y*y+pass*7919)};
+    for(int x=0;x<width;x++) {
