diff --git a/src/components/Modal.tsx b/src/components/Modal.tsx
new file mode 100644
index 0000000..780cf1b
--- /dev/null
+++ b/src/components/Modal.tsx
@@ -0,0 +1,40 @@
+import { useEffect, useRef, type ReactNode } from 'react';
+
+interface Props {
+  id: string;
+  titleId: string;
+  onClose: () => void;
+  children: ReactNode;
+  initialFocus?: string;
+}
+
+export default function Modal({ id, titleId, onClose, children, initialFocus }: Props) {
+  const dialogRef = useRef<HTMLDialogElement>(null);
+
+  useEffect(() => {
+    const dialog = dialogRef.current!;
+    const opener = document.activeElement instanceof HTMLElement ? document.activeElement : null;
+    dialog.showModal();
+    if (initialFocus) dialog.querySelector<HTMLElement>(initialFocus)?.focus();
+    return () => {
+      dialog.close();
+      if (opener?.isConnected) opener.focus();
+    };
+  }, []);
+
+  return (
+    <dialog ref={dialogRef} id={id} aria-labelledby={titleId} className="modal bg-white shadow-xl"
+      onClose={onClose}
+      onClick={event => {
+        if (event.target !== event.currentTarget) return;
+        const bounds = event.currentTarget.getBoundingClientRect();
+        if (event.clientX < bounds.left || event.clientX > bounds.right || event.clientY < bounds.top || event.clientY > bounds.bottom) {
+          event.currentTarget.close();
+        }
+      }}>
+      <button type="button" autoFocus aria-label="Close dialog" onClick={() => dialogRef.current?.close()}
+        className="absolute top-2 right-2 rounded-full p-1 text-gray-600 hover:text-amber-700">✕</button>
+      {children}
+    </dialog>
+  );
+}
