+              <label htmlFor="passkey-name" className="block text-sm font-medium">Passkey display name</label>
+              <p id="name-help" className="mt-1 text-xs leading-5 text-stone-500">Choose a name you recognize, such as “Personal laptop”. This label is used on this site.</p>
+              <input autoFocus id="passkey-name" aria-describedby="name-help" value={name} onChange={e => setName(e.target.value)} maxLength={64} required disabled={busy} className="mt-3 w-full rounded-md border border-stone-300 bg-white px-3 py-2 text-sm focus:outline-emerald-700" />
+              <div className="mt-3 flex gap-2"><button className={`${button} border-stone-900 bg-stone-900 text-white`} disabled={busy || !name.trim() || name.trim() === key.displayName}>{busy ? 'Saving…' : 'Save name'}</button><button type="button" className={`${button} border-stone-300 bg-white`} onClick={() => setEditing(null)} disabled={busy}>Cancel</button></div>
+            </form>}
