+              <div className="mt-3 flex gap-2"><button type="button" disabled={busy} onClick={() => void change('DELETE', key.id)} className={`${button} border-red-700 bg-red-700 text-white`}>{busy ? 'Removing…' : 'Remove passkey'}</button><button autoFocus type="button" disabled={busy} onClick={() => setRemoving(null)} className={`${button} border-stone-300 bg-white`}>Keep passkey</button></div>
+            </div>}
