@@ -0,0 +1,147 @@
+import { test } from 'node:test';
+import assert from 'node:assert/strict';
+import { generateKeyPairSync, createHash, sign } from 'node:crypto';
+import { createAccounts } from '../lib/accounts.mjs';
+
+// Inject only signature verification for deterministic service-policy tests.
+// Production uses SimpleWebAuthn's actual cryptographic verifiers.
+function fixture(t) {
+  let time = 1700000000000;
+  let serial = 0;
+  const accounts = createAccounts({ origin: 'https://coffee.example.com', now: () => time,
+    verifyRegistration: async ({ response }) => {
+      if (response.reject) throw new Error('Invalid attestation');
+      return { verified: true, registrationInfo: { credential: { id: `key-${++serial}`, publicKey: new Uint8Array([1, 2, 3]), counter: 0, transports: ['internal'] }, credentialBackedUp: true } };
+    },
+    verifyAuthentication: async ({ response }) => ({ verified: !response.reject, authenticationInfo: { newCounter: 1, credentialBackedUp: true } }),
+  });
+  t.after(() => accounts.close());
+  const profile = { name: 'Alex Morgan', email: 'Alex@example.com', passkeyName: 'Phone' };
+  async function register(input = profile) {
+    const request = await accounts.registrationOptions(input);
+    const session = await accounts.registrationVerify({ requestId: request.requestId, response: {} });
+    return { session, state: accounts.snapshot(session) };
+  }
+  return { accounts, profile, register, advance: ms => { time += ms; } };
+}
+
+test('registration requests require discoverable passkeys and create no account before verification', async t => {
+  const { accounts, profile } = fixture(t);
+  const request = await accounts.registrationOptions(profile);
+  assert.equal(request.options.rp.id, 'coffee.example.com');
+  assert.equal(request.options.authenticatorSelection.residentKey, 'required');
+  assert.equal(request.options.authenticatorSelection.userVerification, 'required');
+  await assert.rejects(accounts.registrationVerify({ requestId: request.requestId, response: { reject: true } }));
+  const retry = await accounts.registrationOptions(profile);
+  const session = await accounts.registrationVerify({ requestId: retry.requestId, response: {} });
+  assert.equal(accounts.snapshot(session).user.email, 'alex@example.com');
+  await assert.rejects(accounts.registrationVerify({ requestId: retry.requestId, response: {} }), /expired/);
+});
+
+test('sign-in requires a valid, unexpired, single-use challenge and a registered credential', async t => {
+  const { accounts, register, advance } = fixture(t);
+  const { state } = await register();
+  let request = await accounts.authenticationOptions();
+  assert.equal(request.options.userVerification, 'required');
+  await assert.rejects(accounts.authenticationVerify({ requestId: request.requestId, response: { id: state.passkeys[0].id, reject: true } }), /verification failed/);
+  request = await accounts.authenticationOptions();
+  advance(300001);
+  await assert.rejects(accounts.authenticationVerify({ requestId: request.requestId, response: { id: state.passkeys[0].id } }), /expired/);
+  request = await accounts.authenticationOptions();
+  await assert.rejects(accounts.authenticationVerify({ requestId: request.requestId, response: { id: 'unknown-key' } }), /could not sign you in/);
+  request = await accounts.authenticationOptions();
+  const input = { requestId: request.requestId, response: { id: state.passkeys[0].id } };
+  const session = await accounts.authenticationVerify(input);
+  assert.equal(accounts.snapshot(session).user.id, state.user.id);
+  await assert.rejects(accounts.authenticationVerify(input), /expired/);
+});
+
+test('stale sessions require reauthentication and reauth is bound to the current session', async t => {
+  const { accounts, register, advance, profile } = fixture(t);
+  const { session, state } = await register();
+  advance(300001);
+  assert.equal(accounts.snapshot(session).reauthenticate, true);
+  assert.throws(() => accounts.updateProfile(profile, session), /Confirm/);
+  await assert.rejects(accounts.registrationOptions({ passkeyName: 'Backup' }, session, true), /Confirm/);
+  assert.throws(() => accounts.managePasskey(state.passkeys[0].id, { name: 'New name' }, session), /Confirm/);
+  const request = await accounts.authenticationOptions(session, true);
+  await accounts.authenticationVerify({ requestId: request.requestId, response: { id: state.passkeys[0].id } }, session, true);
+  assert.equal(accounts.snapshot(session).reauthenticate, false);
+  assert.equal(accounts.updateProfile({ ...profile, name: 'Alex Updated' }, session).user.name, 'Alex Updated');
+  const login = await accounts.authenticationOptions();
+  const otherSession = await accounts.authenticationVerify({ requestId: login.requestId, response: { id: state.passkeys[0].id } });
+  const bound = await accounts.authenticationOptions(session, true);
+  await assert.rejects(accounts.authenticationVerify({ requestId: bound.requestId, response: { id: state.passkeys[0].id } }, otherSession, true), /Session changed/);
+});
+
+test('passkey management enforces ownership, protects the last key, and revokes other sessions', async t => {
+  const { accounts, register } = fixture(t);
+  const { session, state } = await register();
+  const first = state.passkeys[0].id;
+  assert.throws(() => accounts.managePasskey(first, {}, session, true), /last one/);
+  const secondAccount = await register({ name: 'Other User', email: 'other@example.com', passkeyName: 'Other phone' });
+  assert.throws(() => accounts.managePasskey(first, { name: 'Hijack' }, secondAccount.session), /not found/);
+  const request = await accounts.registrationOptions({ passkeyName: 'Backup' }, session, true);
+  await accounts.registrationVerify({ requestId: request.requestId, response: {} }, session, true);
+  const renamed = accounts.managePasskey(first, { name: 'My phone' }, session);
+  assert.equal(renamed.passkeys[0].name, 'My phone');
+  const login = await accounts.authenticationOptions();
+  const otherSession = await accounts.authenticationVerify({ requestId: login.requestId, response: { id: first } });
+  const remaining = accounts.managePasskey(first, {}, session, true);
+  assert.equal(remaining.passkeys.length, 1);
+  assert.throws(() => accounts.snapshot(otherSession), /sign in/);
+  const revoked = await accounts.authenticationOptions();
+  await assert.rejects(accounts.authenticationVerify({ requestId: revoked.requestId, response: { id: first } }), /could not sign you in/);
+});
+
+test('profiles validate input and reject duplicate emails; logout invalidates the session', async t => {
+  const { accounts, register } = fixture(t);
+  const { session, state } = await register();
+  await register({ name: 'Other User', email: 'other@example.com', passkeyName: 'Phone' });
+  assert.throws(() => accounts.updateProfile({ name: 'Alex', email: 'invalid' }, session), /valid email/);
+  assert.throws(() => accounts.updateProfile({ name: 'Alex', email: 'other@example.com' }, session), /already in use/);
+  const updated = accounts.updateProfile({ name: 'Alex New', email: 'new@example.com' }, session);
+  assert.equal(updated.user.id, state.user.id);
+  assert.equal(updated.passkeys[0].id, state.passkeys[0].id);
+  accounts.logout(session);
+  assert.throws(() => accounts.snapshot(session), /sign in/);
+});
+
+test('a session expires after seven days', async t => {
+  const { accounts, register, advance } = fixture(t);
+  const { session } = await register();
+  advance(7 * 86400000 + 1);
+  assert.throws(() => accounts.snapshot(session), /sign in/);
+});
+
+test('real WebAuthn verification accepts a signed assertion and rejects wrong origin, RP, missing UV, and invalid signatures', async t => {
+  const { privateKey, publicKey } = generateKeyPairSync('ec', { namedCurve: 'prime256v1' });
+  const jwk = publicKey.export({ format: 'jwk' });
+  // COSE EC2 key: kty=2, alg=-7 (ES256), crv=1 (P-256), x and y coordinates.
+  const cose = Buffer.concat([Buffer.from('a5010203262001215820', 'hex'), Buffer.from(jwk.x, 'base64url'), Buffer.from('225820', 'hex'), Buffer.from(jwk.y, 'base64url')]);
+  const credentialId = Buffer.from('test-credential').toString('base64url');
+  const accounts = createAccounts({ origin: 'https://coffee.example.com',
+    verifyRegistration: async () => ({ verified: true, registrationInfo: { credential: { id: credentialId, publicKey: cose, counter: 0, transports: [] }, credentialBackedUp: false } }),
+  });
+  t.after(() => accounts.close());
+  const registration = await accounts.registrationOptions({ name: 'Alex Morgan', email: 'alex@example.com', passkeyName: 'Test authenticator' });
+  const initialSession = await accounts.registrationVerify({ requestId: registration.requestId, response: {} });
+  const userId = accounts.snapshot(initialSession).user.id;
+  let counter = 0;
+  async function assertion({ origin = 'https://coffee.example.com', rp = 'coffee.example.com', flags = 5, badSignature = false } = {}) {
+    const { requestId, options } = await accounts.authenticationOptions();
+    const clientDataJSON = Buffer.from(JSON.stringify({ type: 'webauthn.get', challenge: options.challenge, origin, crossOrigin: false }));
+    const count = Buffer.alloc(4); count.writeUInt32BE(++counter);
+    const authenticatorData = Buffer.concat([createHash('sha256').update(rp).digest(), Buffer.from([flags]), count]);
+    const signature = sign('sha256', Buffer.concat([authenticatorData, createHash('sha256').update(clientDataJSON).digest()]), privateKey);
+    if (badSignature) signature[signature.length - 1] ^= 1;
+    return accounts.authenticationVerify({ requestId, response: { id: credentialId, rawId: credentialId, type: 'public-key', clientExtensionResults: {},
+      response: { clientDataJSON: clientDataJSON.toString('base64url'), authenticatorData: authenticatorData.toString('base64url'), signature: signature.toString('base64url'), userHandle: Buffer.from(userId).toString('base64url') } } });
+  }
+  const signedIn = await assertion();
+  assert.equal(accounts.snapshot(signedIn).user.id, userId);
+  await assert.rejects(assertion({ origin: 'https://attacker.example.com' }));
+  await assert.rejects(assertion({ rp: 'attacker.example.com' }));
+  await assert.rejects(assertion({ flags: 1 }));
+  await assert.rejects(assertion({ badSignature: true }));
+});

