+const test = require('node:test');
+const assert = require('node:assert/strict');
+const fs = require('node:fs');
+const path = require('node:path');
+const { PassThrough } = require('node:stream');
+const { securityHeaders, allowsRequest, receiveReports, summarizeReports } = require('../security');
+const { createRequestHandler } = require('../request-handler');
+
+// In-memory requests only: never import server.js or create/listen on a server.
+function request(handler, { url = '/', method = 'GET', headers = {}, body = '' } = {}) {
+  return new Promise((resolve, reject) => {
+    const req = new PassThrough();
+    Object.assign(req, { url, method, headers });
+    const responseHeaders = {};
+    const res = {
+      setHeader(name, value) { responseHeaders[name.toLowerCase()] = value; },
+      writeHead(status, extra = {}) {
+        this.status = status;
+        for (const [name, value] of Object.entries(extra)) this.setHeader(name, value);
+      },
+      end(data) {
+        resolve({ status: this.status, headers: responseHeaders, body: data?.toString() || '' });
+      },
+    };
+    try {
+      handler(req, res);
+      req.end(body);
+    } catch (error) { reject(error); }
+  });
+}
+
+test('CSP enforces no scripts or DOM injection policies without unsafe allowances', () => {
+  const headers = securityHeaders();
+  const csp = headers['Content-Security-Policy'];
+  for (const directive of ["default-src 'none'", "script-src 'none'", "style-src 'self'",
+    "object-src 'none'", "base-uri 'none'", "form-action 'self'", "frame-ancestors 'self'",
+    "require-trusted-types-for 'script'", "trusted-types 'none'", 'report-to csp',
+    'report-uri /security-reports']) assert.ok(csp.split('; ').includes(directive), directive);
+  assert.doesNotMatch(csp, /unsafe-inline|unsafe-eval|\*/);
+  assert.equal(headers['Reporting-Endpoints'], 'csp="/security-reports"');
+  assert.equal(headers['X-Content-Type-Options'], 'nosniff');
+  assert.equal(headers['X-Frame-Options'], 'SAMEORIGIN');
+  assert.equal(headers['Cross-Origin-Opener-Policy'], 'same-origin-allow-popups');
+  assert.equal(headers['Cross-Origin-Resource-Policy'], 'same-origin');
+  assert.equal(headers['Referrer-Policy'], 'strict-origin-when-cross-origin');
+  assert.match(headers['Permissions-Policy'], /camera=\(\).*microphone=\(\).*geolocation=\(\)/);
+  assert.equal(headers['Cross-Origin-Embedder-Policy'], undefined);
+});
+
+test('report-only rollout and short HSTS are explicit deployment options', () => {
+  const defaults = securityHeaders();
+  assert.equal(defaults['Strict-Transport-Security'], undefined);
+  const staged = securityHeaders({ reportOnly: true, https: true });
+  assert.equal(staged['Content-Security-Policy'], undefined);
+  assert.equal(staged['Content-Security-Policy-Report-Only'], defaults['Content-Security-Policy']);
+  assert.equal(staged['Strict-Transport-Security'], 'max-age=300');
+  assert.equal(staged['X-Frame-Options'], 'SAMEORIGIN');
+});
+
+test('markup and CSS fit the enforced policy', () => {
+  const html = fs.readFileSync(path.join(__dirname, '../index.html'), 'utf8');
+  const css = fs.readFileSync(path.join(__dirname, '../styles.css'), 'utf8');
+  assert.doesNotMatch(html, /<script\b|<style\b|\sstyle\s*=|\son\w+\s*=|javascript:|<base\b/i);
+  assert.match(html, /<link rel="stylesheet" href="\/styles.css">/);
+  assert.match(html, /<form action="\/logout" method="post">/);
+  const policy = securityHeaders()['Content-Security-Policy'];
+  for (const [, url] of css.matchAll(/url\(['"]?(https:[^'")]+)['"]?\)/g)) {
+    assert.ok(policy.split('; ').find(d => d.startsWith('img-src ')).split(' ').includes(new URL(url).origin));
+  }
+  assert.doesNotMatch(css, /@import|expression\s*\(|javascript:/i);
+});
+
+test('Fetch Metadata blocks foreign subresources and POSTs while retaining public links', () => {
+  for (const site of ['same-origin', 'none', undefined]) {
+    assert.equal(allowsRequest({ method: 'POST', headers: { 'sec-fetch-site': site } }), true);
+  }
+  for (const site of ['cross-site', 'same-site']) {
+    assert.equal(allowsRequest({ method: 'POST', headers: { 'sec-fetch-site': site } }), false);
+    assert.equal(allowsRequest({ method: 'GET', headers: { 'sec-fetch-site': site } }), false);
+    assert.equal(allowsRequest({ method: 'GET', headers: {
+      'sec-fetch-site': site, 'sec-fetch-mode': 'navigate', 'sec-fetch-dest': 'document',
+    } }), true);
+    assert.equal(allowsRequest({ method: 'GET', headers: {
+      'sec-fetch-site': site, 'sec-fetch-mode': 'navigate', 'sec-fetch-dest': 'object',
+    } }), false);
+  }
+});
+
+test('documents, deep links, and stylesheet have correct types and security headers', async () => {
+  const handler = createRequestHandler();
+  for (const url of ['/', '/menu/seasonal', '/styles.css', '/server.js', '/../../security.js']) {
+    const res = await request(handler, { url });
+    assert.equal(res.status, 200);
+    assert.ok(res.headers['content-security-policy']);
+    assert.match(res.headers.vary, /Sec-Fetch-Site/);
+    assert.equal(res.headers['cache-control'], 'no-store');
+    assert.equal(res.headers['content-type'], url === '/styles.css' ? 'text/css; charset=utf-8' : 'text/html; charset=utf-8');
+    assert.match(res.body, url === '/styles.css' ? /:root/ : /<!DOCTYPE html>/);
+  }
+  const head = await request(handler, { method: 'HEAD', url: '/styles.css' });
+  assert.equal(head.status, 200);
+  assert.equal(head.body, '');
+});
+
+test('logout requires POST, clears browser data, and rejects cross-site forms', async () => {
+  const handler = createRequestHandler();
+  const get = await request(handler, { url: '/logout' });
+  assert.equal(get.status, 405);
+  assert.equal(get.headers.allow, 'POST');
+  assert.equal(get.headers['clear-site-data'], undefined);
+  const post = await request(handler, { url: '/logout/', method: 'POST', headers: { 'sec-fetch-site': 'same-origin' } });
+  assert.equal(post.status, 200);
+  assert.equal(post.headers['clear-site-data'], '"cookies", "storage", "cache"');
+  const foreign = await request(handler, { url: '/logout', method: 'POST', headers: { 'sec-fetch-site': 'cross-site' } });
+  assert.equal(foreign.status, 403);
+  assert.equal(foreign.headers['clear-site-data'], undefined);
+  assert.ok(foreign.headers['content-security-policy']);
+});
+
+test('logout falls back to exact Origin checks when Fetch Metadata is unavailable', async () => {
+  const handler = createRequestHandler({ https: true });
+  for (const [headers, expected] of [
+    [{ host: 'coffee.example', origin: 'https://coffee.example' }, 200],
+    [{ host: 'coffee.example', origin: 'https://evil.example' }, 403],
+    [{ host: 'coffee.example', origin: 'http://coffee.example' }, 403],
+    [{ host: 'coffee.example', origin: 'null' }, 403],
+    [{ host: 'coffee.example' }, 403],
+    [{ host: 'coffee.example', origin: 'https://evil.example', 'sec-fetch-site': 'same-origin' }, 403],
+  ]) {
+    const res = await request(handler, { url: '/logout', method: 'POST', headers });
+    assert.equal(res.status, expected);
+  }
+});
+
+test('bad URLs and unsupported methods retain security headers', async () => {
+  const handler = createRequestHandler();
+  for (const [options, status] of [[{ url: 'http://[' }, 400], [{ method: 'PUT' }, 405], [{ url: '/security-reports' }, 405]]) {
+    const res = await request(handler, options);
+    assert.equal(res.status, status);
+    assert.equal(res.headers['x-content-type-options'], 'nosniff');
+  }
+});
+
+test('both reporting formats produce only allowlisted counts', async () => {
+  const logs = [];
+  const handler = (req, res) => receiveReports(req, res, (...args) => logs.push(args));
+  const legacy = { 'csp-report': {
+    'effective-directive': 'script-src-elem', disposition: 'enforce',
+    'document-uri': 'https://example.com/?secret=123', 'script-sample': 'private content',
+  } };
+  const modern = [{ type: 'csp-violation', url: 'https://example.com/?token=123', body: {
+    effectiveDirective: 'trusted-types', disposition: 'report', sample: 'private content',
+  } }];
+  for (const [type, payload] of [['application/csp-report', legacy], ['application/reports+json', modern]]) {
+    const res = await request(handler, { headers: { 'content-type': `${type}; charset=utf-8` }, body: JSON.stringify(payload) });
+    assert.equal(res.status, 204);
+  }
+  assert.deepEqual(logs, [
+    ['CSP violation counts', { 'enforce:script-src-elem': 1 }],
+    ['CSP violation counts', { 'report:trusted-types': 1 }],
+  ]);
+  assert.doesNotMatch(JSON.stringify(logs), /secret|token|private|https:/);
+  assert.deepEqual(summarizeReports({ 'csp-report': { 'effective-directive': '__proto__' } }), {});
+});
+
+test('reports reject oversized, malformed, wrong-type and excessive batches without logging', async () => {
+  const logs = [];
+  const handler = (req, res) => receiveReports(req, res, (...args) => logs.push(args));
+  for (const [body, contentType, status] of [
+    ['x'.repeat(16385), 'application/csp-report', 413],
+    ['{', 'application/csp-report', 400],
+    ['null', 'application/csp-report', 400],
+    ['{}', 'text/plain', 415],
+    [JSON.stringify(Array.from({ length: 101 }, () => ({ type: 'csp-violation', body: {} }))), 'application/reports+json', 400],
+  ]) {
+    const res = await request(handler, { body, headers: { 'content-type': contentType } });
+    assert.equal(res.status, status);
+  }
+  assert.deepEqual(logs, []);
+});
+
+test('report route responds explicitly instead of returning the HTML fallback', async () => {
+  const res = await request(createRequestHandler({ reportOnly: true }), {
+    url: '/security-reports', method: 'POST', headers: { 'content-type': 'application/csp-report' },
+    body: JSON.stringify({ 'csp-report': { 'effective-directive': 'unknown' } }),
+  });
+  assert.equal(res.status, 204);
+  assert.ok(res.headers['content-security-policy-report-only']);
+  assert.equal(res.body, '');
+});

