+    hasher,
+    verifier: async (data, signature) => {
+      const compact = `${data}.${signature}`;
+      try { await jwtVerify(compact, issuerKeys, evtOptions); }
+      catch (error) {
+        if (error.code !== 'ERR_JWKS_MULTIPLE_MATCHING_KEYS') throw error;
+        let matched = false;
+        for await (const key of error) {
+          try { await jwtVerify(compact, key, evtOptions); matched = true; break; } catch {}
+        }
+        if (!matched) throw error;
+      }
+      return true;
+    },
+    kbVerifier: async (data, signature) => {
+      const key = payload.cnf?.jwk;
+      const alg = decoded.kbJwt.header.alg;
+      const normalize = value => value === 'Ed25519' ? 'EdDSA' : value;
+      if (!key || key.d || key.k || !algorithms.includes(alg) || !algorithms.includes(key.alg) || normalize(alg) !== normalize(key.alg)) throw new Error('Invalid holder key');
