+      return true;
+    }
+  });
+  const verified = await verifier.verify(rawToken, { requiredClaimKeys:['email','email_verified'], keyBindingNonce:nonce, expectedKeyBindingAudience:audience, keyBindingMaxAgeSeconds:300, skewSeconds:60 });
+  if (verified.payload.email_verified !== true || typeof verified.payload.email !== 'string' || verified.payload.email.toLowerCase() !== email.toLowerCase()) throw new Error('Email mismatch');
+}
